const CONFIG = {
  bookingToken: 'rlwqer5f50usxidldnhdzyg7',
  pbBase: 'http://pocketbase:8090',
  evoBase: 'http://evolution-api:8080',
  evoKey: 'clinic_secret_key_123',
  evoInstance: 'clinic_default'
};

function pickText(msg) {
  if (!msg) return '';
  if (typeof msg === 'string') return msg;
  if (typeof msg.conversation === 'string') return msg.conversation;
  if (msg.extendedTextMessage && msg.extendedTextMessage.text) return msg.extendedTextMessage.text;
  if (msg.imageMessage && msg.imageMessage.caption) return msg.imageMessage.caption;
  if (msg.videoMessage && msg.videoMessage.caption) return msg.videoMessage.caption;
  if (msg.documentMessage && msg.documentMessage.caption) return msg.documentMessage.caption;
  if (msg.ephemeralMessage && msg.ephemeralMessage.message) return pickText(msg.ephemeralMessage.message);
  if (msg.viewOnceMessage && msg.viewOnceMessage.message) return pickText(msg.viewOnceMessage.message);
  if (msg.viewOnceMessageV2 && msg.viewOnceMessageV2.message) return pickText(msg.viewOnceMessageV2.message);
  if (msg.buttonsResponseMessage) {
    return msg.buttonsResponseMessage.selectedDisplayText || msg.buttonsResponseMessage.selectedButtonId || '';
  }
  if (msg.listResponseMessage) {
    const l = msg.listResponseMessage;
    return l.title || (l.singleSelectReply && l.singleSelectReply.selectedRowId) || '';
  }
  return '';
}

function hasVoice(msg) {
  if (!msg || typeof msg !== 'object') return false;
  return !!(msg.audioMessage || msg.pttMessage || msg.ptt || msg.voiceMessage);
}

function unwrap(raw) {
  if (!raw || typeof raw !== 'object') return {};
  if (raw.body && (raw.body.data || raw.body.key || raw.body.message)) return unwrap(raw.body);
  let inner = raw.data || raw;
  if (Array.isArray(inner)) {
    inner = inner.find(function (item) {
      return item && item.key && item.key.fromMe !== true;
    }) || inner[inner.length - 1] || {};
  }
  if (inner.data && (inner.key == null)) return unwrap(inner);
  return inner;
}

function realJid(key, inner, raw) {
  const k = key || {};
  const candidates = [
    k.remoteJidAlt,
    k.senderPn,
    k.participantAlt,
    k.remoteJid,
    inner.remoteJidAlt,
    inner.senderPn,
    inner.remoteJid,
    raw.sender,
    raw.senderPn
  ];
  let lidFallback = '';
  for (let i = 0; i < candidates.length; i++) {
    const v = String(candidates[i] || '');
    if (!v) continue;
    if (v.indexOf('@g.us') >= 0) return v;
    if (v.indexOf('@lid') >= 0) {
      if (!lidFallback) lidFallback = v;
      continue;
    }
    if (v.indexOf('@s.whatsapp.net') >= 0 || v.indexOf('@c.us') >= 0) return v;
    if (/^\d{10,15}$/.test(v.replace(/\D/g, '')) && v.indexOf('@') < 0) return v + '@s.whatsapp.net';
  }
  return lidFallback;
}

function isStopText(text) {
  const t = String(text || '').toLowerCase().replace(/[^\w\s]/g, ' ').replace(/\s+/g, ' ').trim();
  if (!t) return false;
  return (
    t === 'stop' ||
    t === 'unsubscribe' ||
    t === 'opt out' ||
    t === 'optout' ||
    t.indexOf('stop messages') >= 0 ||
    t.indexOf('do not message') >= 0 ||
    t.indexOf('dont message') >= 0 ||
    t.indexOf("don't message") >= 0 ||
    t.indexOf('stop promotions') >= 0
  );
}

const raw = $input.first().json || {};
const inner = unwrap(raw);
const key = inner.key || {};
const msg = inner.message || inner;
const chatJid = String(key.remoteJid || inner.remoteJid || '');
const jid = realJid(key, inner, raw);
const fromMe = key.fromMe === true;
const isGroup =
  chatJid.indexOf('@g.us') >= 0 ||
  chatJid.indexOf('@broadcast') >= 0 ||
  chatJid.indexOf('@newsletter') >= 0 ||
  String(jid).indexOf('@g.us') >= 0;
const isStatus = chatJid.indexOf('status@broadcast') >= 0;
const phone = jid.replace(/@.*$/, '').replace(/\D/g, '');
const name = String(inner.pushName || raw.pushName || '').trim();
const voice = hasVoice(msg);
let text = String(pickText(msg) || '').trim();
if (!text && voice) text = '[voice note]';
const optOut = !fromMe && isStopText(text);
let skipReason = '';
if (isGroup) skipReason = 'group';
else if (isStatus) skipReason = 'status';
else if (!phone) skipReason = 'noPhone';
const skip = skipReason !== '';
const staffReply = !skip && fromMe;
const choice = parseInt(text, 10);
const wantsBook = !skip && !fromMe && String(choice) === text && choice >= 1 && choice <= 12;

return [{
  json: Object.assign({}, CONFIG, {
    skip: skip,
    skipReason: skipReason,
    staffReply: staffReply,
    optOut: optOut,
    voice: voice,
    wantsBook: wantsBook,
    slotIndex: wantsBook ? choice - 1 : -1,
    phone: phone,
    name: name,
    text: text,
    jid: jid
  })
}];

const inbound = $('Parse inbound').first().json || {};
const up = $input.first().json || {};
const groupJid =
  up.staffGroupJid || '120363426681576301@g.us';
const optOut = inbound.optOut === true || up.optOut === true;
const shouldReply = up.shouldReply !== false && !optOut;
const sendWelcome = shouldReply && up.isNewLead === true && !!(up.welcomeText || '').trim();
return [{
  json: Object.assign({}, inbound, {
    shouldReply: shouldReply,
    sendWelcome: sendWelcome,
    notifyGroup: up.notifyGroup === true,
    staffGroupJid: groupJid,
    groupText: up.groupText || '',
    welcomeText: up.welcomeText || '',
    optOutText: up.optOutText || '',
    number: inbound.phone,
    reply: up.groupText || '',
    isReturningPatient: up.isReturningPatient === true,
    isNewLead: up.isNewLead === true,
    optOut: optOut
  })
}];

const p = $input.first().json || {};
return [{
  json: Object.assign({}, p, {
    number: p.staffGroupJid || '120363426681576301@g.us',
    reply: p.groupText || ''
  })
}];

const p = $input.first().json || {};
return [{
  json: Object.assign({}, p, {
    number: p.phone,
    reply: p.optOutText || ''
  })
}];

const p = $input.first().json || {};
return [{
  json: Object.assign({}, p, {
    number: p.phone,
    reply: p.welcomeText || ''
  })
}];

const ctx = $('Get AI context').first().json || {};
const inbound = $('Parse inbound').first().json || {};
const slots = (ctx.slots || []).slice(0, 8).map(function (s, i) {
  return (i + 1) + '. ' + s.start;
});
const maps = (ctx.evolution && ctx.evolution.googleMapsUrl) || ctx.googleMapsUrl || '';
const treatments = (ctx.campaign && ctx.campaign.treatments) || '';
const system =
  'You are the WhatsApp assistant for a dental clinic named ' +
  (ctx.clinicName || 'the clinic') +
  '. Speak briefly and warmly in 1-3 short messages. Never book an appointment yourself. ' +
  'Do not send welcome packs, appointment confirmations, reminders, birthday wishes, Google review requests, or staff-group alerts — those are sent only from saved clinic templates. You only chat: answer questions, collect name and concern, and say staff will call. ' +
  'NEVER mention prices, fees, packages, discounts, EMI, or cost. If they ask how much something costs, say only a doctor can discuss fees in person or on a phone call. ' +
  'You may name treatments from this list only, with no prices: ' + treatments + '. ' +
  'If you do not yet have their real name, politely ask for it. ' +
  'Ask what dental concern they have. ' +
  'If the inbound text is [voice note], thank them and ask them to type the concern, or say staff will call. ' +
  'If the person is interested or says yes, thank them and say the receptionist or doctor will call to confirm. ' +
  'If they want to reschedule, say staff will call to pick a new time. ' +
  'If they say they already left a Google review, thank them. ' +
  'You may share the clinic Google Maps link if they ask where you are: ' + maps + '. ' +
  'You may mention a clinic flyer only if campaign.sendFlyerWithChat is true. ' +
  'Reply in the patient language. Return ONLY JSON with keys: ' +
  'reply (string), attachFlyer (boolean), events (array of {type, appointmentId?, name?, interest?}). ' +
  'type must be one of: interested, reschedule, review_done, profile.';

const user =
  'Incoming WhatsApp from ' + inbound.phone +
  ' name=' + (inbound.name || '') +
  ' text=' + (inbound.text || '') +
  '\nLead: ' + JSON.stringify(ctx.lead || null) +
  '\nPatient: ' + JSON.stringify(ctx.patient || null) +
  '\nUpcoming appointments: ' + JSON.stringify(ctx.upcomingAppointments || []) +
  '\nFree slots (info only): ' + slots.join('\n') +
  '\nGoogle review URL: ' + ((ctx.campaign && ctx.campaign.googleReviewUrl) || '') +
  '\nSend flyer allowed: ' + !!(ctx.campaign && ctx.campaign.sendFlyerWithChat && ctx.flyer && ctx.flyer.url);

return [{
  json: {
    evoBase: inbound.evoBase,
    evoKey: inbound.evoKey,
    evoInstance: inbound.evoInstance,
    pbBase: inbound.pbBase,
    bookingToken: inbound.bookingToken,
    phone: inbound.phone,
    name: inbound.name,
    number: inbound.phone,
    flyerUrl: ctx.flyer && ctx.flyer.url
      ? (inbound.pbBase + ctx.flyer.url)
      : ((ctx.campaign && ctx.campaign.marketingImageUrl) || ''),
    sendFlyerAllowed: !!(ctx.campaign && ctx.campaign.sendFlyerWithChat && (
      (ctx.flyer && ctx.flyer.file) || (ctx.campaign && ctx.campaign.marketingImageUrl)
    )),
    googleMapsUrl: maps,
    model: (ctx.campaign && ctx.campaign.openrouterModel) || 'openai/gpt-4o-mini',
    openRouterBody: {
      model: (ctx.campaign && ctx.campaign.openrouterModel) || 'openai/gpt-4o-mini',
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user }
      ]
    }
  }
}];

const prev = $('Build AI prompt').first().json || {};
const raw = $input.first().json || {};
let content = '';
if (raw.choices && raw.choices[0] && raw.choices[0].message) {
  content = raw.choices[0].message.content || '';
}
let parsed = { reply: '', attachFlyer: false, events: [] };
try {
  parsed = JSON.parse(content);
} catch (e) {
  parsed.reply = content || 'Thank you. Our receptionist will help you shortly.';
}
const events = parsed.events || [];
if (parsed.markInterested) events.push({ type: 'interested' });
if (parsed.reschedule) events.push({ type: 'reschedule' });
if (parsed.reviewDone) events.push({ type: 'review_done' });
events.push({ type: 'assistant_replied' });

return [{
  json: {
    evoBase: prev.evoBase,
    evoKey: prev.evoKey,
    evoInstance: prev.evoInstance,
    phone: prev.phone,
    name: prev.name,
    number: prev.phone,
    reply: String(parsed.reply || 'Thank you. Our team will call you to confirm.'),
    attachFlyer: !!(parsed.attachFlyer && prev.sendFlyerAllowed && prev.flyerUrl),
    flyerUrl: prev.flyerUrl,
    events: events,
    event0: events[0] || null,
    event1: events[1] || null,
    event2: events[2] || null
  }
}];

const prev = $input.first().json || {};
const events = prev.events || [];
if (!events.length) return [];
return events.map(function (ev) {
  return {
    json: {
      phone: prev.phone,
      name: prev.name,
      type: ev.type,
      appointmentId: ev.appointmentId || '',
      name: ev.name || prev.name,
      interest: ev.interest || ''
    }
  };
});
